import{_ as t,o as a,c as o,a1 as i}from"./chunks/framework.DQ_lpCRI.js";const u=JSON.parse('{"title":"Frequently Asked Questions","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md"}'),r={name:"faq.md"};function n(s,e,h,l,d,c){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h1><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><h3 id="what-makes-this-different-from-a-normal-mobile-hotspot" tabindex="-1">What makes this different from a normal mobile hotspot? <a class="header-anchor" href="#what-makes-this-different-from-a-normal-mobile-hotspot" aria-label="Permalink to &quot;What makes this different from a normal mobile hotspot?&quot;">​</a></h3><p>Normal mobile hotspots use Android&#39;s built-in tethering API, which carriers can detect and throttle/block. This app uses <strong>Wi-Fi Direct</strong> (a peer-to-peer protocol) to create a direct connection between devices, which carriers see as regular phone-to-phone communication — not tethering.</p><h3 id="do-i-need-root-access" tabindex="-1">Do I need root access? <a class="header-anchor" href="#do-i-need-root-access" aria-label="Permalink to &quot;Do I need root access?&quot;">​</a></h3><p>No. The app uses only standard Android APIs — <strong>VpnService</strong> and <strong>Wi-Fi Direct (WifiP2pManager)</strong>. No root access is required on either the host or client phone.</p><h3 id="does-the-app-work-on-any-android-phone" tabindex="-1">Does the app work on any Android phone? <a class="header-anchor" href="#does-the-app-work-on-any-android-phone" aria-label="Permalink to &quot;Does the app work on any Android phone?&quot;">​</a></h3><p>Any phone running <strong>Android 7.0 (API 24)</strong> or higher with <strong>Wi-Fi Direct</strong> support should work. Most modern Android phones support Wi-Fi Direct.</p><h3 id="will-this-work-with-my-carrier" tabindex="-1">Will this work with my carrier? <a class="header-anchor" href="#will-this-work-with-my-carrier" aria-label="Permalink to &quot;Will this work with my carrier?&quot;">​</a></h3><p>The app is designed to bypass carrier hotspot detection, but we cannot guarantee it works with every carrier in every country. Results may vary depending on your carrier&#39;s detection methods.</p><h3 id="is-this-legal" tabindex="-1">Is this legal? <a class="header-anchor" href="#is-this-legal" aria-label="Permalink to &quot;Is this legal?&quot;">​</a></h3><p>In most countries, using a VPN and Wi-Fi Direct to share your connection is legal. However, tethering restrictions in your carrier&#39;s terms of service may prohibit this. Check your carrier&#39;s terms before using.</p><hr><h2 id="setup-usage" tabindex="-1">Setup &amp; Usage <a class="header-anchor" href="#setup-usage" aria-label="Permalink to &quot;Setup &amp; Usage&quot;">​</a></h2><h3 id="why-does-the-app-need-location-permission" tabindex="-1">Why does the app need location permission? <a class="header-anchor" href="#why-does-the-app-need-location-permission" aria-label="Permalink to &quot;Why does the app need location permission?&quot;">​</a></h3><p>Android requires location permission for Wi-Fi Direct discovery and connection. The app does not use your actual GPS location — it only uses the permission because the Android API demands it.</p><h3 id="what-is-private-dns-and-why-should-i-disable-it" tabindex="-1">What is &quot;Private DNS&quot; and why should I disable it? <a class="header-anchor" href="#what-is-private-dns-and-why-should-i-disable-it" aria-label="Permalink to &quot;What is &quot;Private DNS&quot; and why should I disable it?&quot;">​</a></h3><p>Private DNS (DNS over TLS) can interfere with the SOCKS5 proxy. If you have a custom Private DNS provider set (like <code>dns.google</code>), the app will show a warning. Set it to <strong>Off</strong> or <strong>Automatic</strong> in your phone&#39;s network settings.</p><h3 id="can-i-use-both-host-and-client-mode-at-the-same-time" tabindex="-1">Can I use both Host and Client mode at the same time? <a class="header-anchor" href="#can-i-use-both-host-and-client-mode-at-the-same-time" aria-label="Permalink to &quot;Can I use both Host and Client mode at the same time?&quot;">​</a></h3><p>No. The app prevents running both modes simultaneously to avoid conflicts. You&#39;ll see a warning if you try to switch modes while one is active.</p><h3 id="why-does-the-service-stop-when-i-close-the-app" tabindex="-1">Why does the service stop when I close the app? <a class="header-anchor" href="#why-does-the-service-stop-when-i-close-the-app" aria-label="Permalink to &quot;Why does the service stop when I close the app?&quot;">​</a></h3><p>The app uses a <strong>Foreground Service</strong> to keep running, but some phones (especially Xiaomi, Huawei, OnePlus) have aggressive battery management that can kill foreground services. Make sure to:</p><ul><li>Grant <strong>Ignore battery optimization</strong> permission</li><li>Add the app to your phone&#39;s <strong>protected apps</strong> or <strong>auto-start</strong> list</li><li>Lock the app in your recent apps list</li></ul><h3 id="how-far-apart-can-the-devices-be" tabindex="-1">How far apart can the devices be? <a class="header-anchor" href="#how-far-apart-can-the-devices-be" aria-label="Permalink to &quot;How far apart can the devices be?&quot;">​</a></h3><p>Wi-Fi Direct typically works within <strong>30-50 meters</strong> (100-165 feet) with line of sight. Walls and obstacles reduce the range.</p><hr><h2 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h2><h3 id="what-internet-speeds-should-i-expect" tabindex="-1">What internet speeds should I expect? <a class="header-anchor" href="#what-internet-speeds-should-i-expect" aria-label="Permalink to &quot;What internet speeds should I expect?&quot;">​</a></h3><p>Speeds depend on:</p><ul><li>Your phone&#39;s cellular connection speed</li><li>Wi-Fi Direct bandwidth (typically 30-50 Mbps real-world)</li><li>Distance and obstacles between devices</li><li>Band selection (5GHz is faster, 2.4GHz has better range)</li></ul><p>Real-world: <strong>10-40 Mbps</strong> is typical for most setups.</p><h3 id="is-this-good-for-gaming" tabindex="-1">Is this good for gaming? <a class="header-anchor" href="#is-this-good-for-gaming" aria-label="Permalink to &quot;Is this good for gaming?&quot;">​</a></h3><p>Yes. The app is specifically designed with gaming in mind:</p><ul><li><strong>5GHz band</strong> option for lower latency</li><li><strong>UDP support</strong> in the SOCKS5 proxy for real-time game traffic</li><li><strong>Windows TUN adapter</strong> for full game compatibility</li><li><strong>ICS bridge</strong> for consoles (PS5, Xbox, Switch)</li></ul><p>Typical ping: <strong>30-60ms</strong> added on top of the phone&#39;s cellular latency.</p><h3 id="will-streaming-work-netflix-youtube-etc" tabindex="-1">Will streaming work (Netflix, YouTube, etc.)? <a class="header-anchor" href="#will-streaming-work-netflix-youtube-etc" aria-label="Permalink to &quot;Will streaming work (Netflix, YouTube, etc.)?&quot;">​</a></h3><p>Yes. The SOCKS5 proxy handles TCP traffic (streaming) and UDP traffic (gaming/chat). Streaming services work normally.</p><hr><h2 id="windows-client" tabindex="-1">Windows Client <a class="header-anchor" href="#windows-client" aria-label="Permalink to &quot;Windows Client&quot;">​</a></h2><h3 id="why-does-the-windows-client-need-administrator-privileges" tabindex="-1">Why does the Windows client need Administrator privileges? <a class="header-anchor" href="#why-does-the-windows-client-need-administrator-privileges" aria-label="Permalink to &quot;Why does the Windows client need Administrator privileges?&quot;">​</a></h3><p>The app needs admin rights to create and configure the TUN virtual adapter and modify system routing tables. This is normal for VPN software on Windows.</p><h3 id="can-i-use-the-windows-client-on-a-desktop-pc" tabindex="-1">Can I use the Windows client on a desktop PC? <a class="header-anchor" href="#can-i-use-the-windows-client-on-a-desktop-pc" aria-label="Permalink to &quot;Can I use the Windows client on a desktop PC?&quot;">​</a></h3><p>Yes, as long as it has Wi-Fi (to connect to the phone&#39;s Wi-Fi Direct network). Desktop PCs without Wi-Fi can use a USB Wi-Fi adapter.</p><h3 id="does-the-windows-client-work-on-mac" tabindex="-1">Does the Windows client work on Mac? <a class="header-anchor" href="#does-the-windows-client-work-on-mac" aria-label="Permalink to &quot;Does the Windows client work on Mac?&quot;">​</a></h3><p>No, the desktop client is Windows-only. However, Macs can connect through the <strong>ICS bridge method</strong> — connect a Windows laptop via VPN, then share the connection to the Mac via hotspot.</p><hr><h2 id="consoles-tvs" tabindex="-1">Consoles &amp; TVs <a class="header-anchor" href="#consoles-tvs" aria-label="Permalink to &quot;Consoles &amp; TVs&quot;">​</a></h2><h3 id="can-i-connect-my-ps5-directly-to-the-phone" tabindex="-1">Can I connect my PS5 directly to the phone? <a class="header-anchor" href="#can-i-connect-my-ps5-directly-to-the-phone" aria-label="Permalink to &quot;Can I connect my PS5 directly to the phone?&quot;">​</a></h3><p>Not directly. The PS5 cannot run the Android app or connect to SOCKS5 proxies natively. You need a <strong>Windows laptop as a bridge</strong> (see the <a href="/Hotspot-Bypass-VPN-Unlimited-Hotspot/guide/non-app-devices">Non-App Device Guide</a>).</p><h3 id="does-bridge-mode-add-latency" tabindex="-1">Does bridge mode add latency? <a class="header-anchor" href="#does-bridge-mode-add-latency" aria-label="Permalink to &quot;Does bridge mode add latency?&quot;">​</a></h3><p>Yes, but usually only <strong>5-15ms</strong> extra. For most games, this is perfectly acceptable.</p><h3 id="do-i-need-a-separate-wi-fi-adapter-for-the-laptop" tabindex="-1">Do I need a separate Wi-Fi adapter for the laptop? <a class="header-anchor" href="#do-i-need-a-separate-wi-fi-adapter-for-the-laptop" aria-label="Permalink to &quot;Do I need a separate Wi-Fi adapter for the laptop?&quot;">​</a></h3><p>Some laptops can run both VPN and mobile hotspot on the same Wi-Fi adapter, but not all. If you have issues, a <strong>USB Wi-Fi adapter</strong> (as low as $10-15) dedicated to the hotspot solves the problem.</p>',53)])])}const m=t(r,[["render",n]]);export{u as __pageData,m as default};
